INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24001, "アヤネ", 0, 102301, "2030/12/17 14:59:59", 2, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 24, "2020/07/31 12:00:00", 0, 401);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24002, "アヤネ", 2.21, 102301, "2030/12/17 14:59:59", 2, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 24, "2020/07/31 12:00:00", 0, 402);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24003, "アヤネ", 0, 102301, "2030/12/17 14:59:59", 2, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 24, "2020/07/31 12:00:00", 0, 403);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24004, "アサヒ", 1.99, 192201, "2030/12/17 14:59:59", 1, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 24, "2020/07/31 12:00:00", 0, 701);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24005, "アサヒ", 2.21, 192201, "2030/12/17 14:59:59", 2, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 24, "2020/07/31 12:00:00", 0, 702);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24006, "アサヒ", 3.33, 192201, "2030/12/17 14:59:59", 1, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 24, "2020/07/31 12:00:00", 0, 703);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24007, "部員３", 0, 192301, "2030/12/17 14:59:59", 2, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 24, "2020/07/31 12:00:00", 0, 801);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24008, "部員３", 2.68, 192301, "2030/12/17 14:59:59", 2, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 24, "2020/07/31 12:00:00", 0, 802);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24009, "部員３", 0, 192301, "2030/12/17 14:59:59", 2, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 24, "2020/07/31 12:00:00", 0, 803);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24010, "", 0, 192501, "2030/12/17 14:59:59", 1, "やった！", 24, "2020/07/31 12:00:00", 0, 501);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24011, "", 0, 192501, "2030/12/17 14:59:59", 1, "勝ったよ！", 24, "2020/07/31 12:00:00", 0, 502);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24012, "", 0, 192501, "2030/12/17 14:59:59", 1, "いい調子！", 24, "2020/07/31 12:00:00", 0, 503);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 6, 24013, "ミサト", 5.33, 113501, "2030/12/17 14:59:59", 2, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 24, "2020/07/31 12:00:00", 0, 111);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24014, "ミサト", 6.85, 113501, "2030/12/17 14:59:59", 2, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 24, "2020/07/31 12:00:00", 0, 112);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24015, "ミサト", 3, 113501, "2030/12/17 14:59:59", 2, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 24, "2020/07/31 12:00:00", 0, 113);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24016, "ダイチ", 6.11, 192401, "2030/12/17 14:59:59", 2, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 24, "2020/07/31 12:00:00", 0, 611);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24017, "ダイチ", 6.75, 192401, "2030/12/17 14:59:59", 2, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 24, "2020/07/31 12:00:00", 0, 612);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24018, "ダイチ", 0, 192401, "2030/12/17 14:59:59", 2, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 24, "2020/07/31 12:00:00", 0, 613);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24019, "ハツネ", 4.52, 113401, "2030/12/17 14:59:59", 1, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 24, "2020/07/31 12:00:00", 0, 211);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24020, "ハツネ", 3.89, 113401, "2030/12/17 14:59:59", 1, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 24, "2020/07/31 12:00:00", 0, 212);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24021, "ハツネ", 13.49, 113401, "2030/12/17 14:59:59", 2, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 24, "2020/07/31 12:00:00", 0, 213);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24022, "カヤ", 3.17, 106501, "2030/12/17 14:59:59", 2, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 24, "2020/07/31 12:00:00", 0, 311);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24023, "カヤ", 4.42, 106501, "2030/12/17 14:59:59", 2, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 24, "2020/07/31 12:00:00", 0, 312);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 6, 24024, "カヤ", 2.89, 106501, "2030/12/17 14:59:59", 1, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 24, "2020/07/31 12:00:00", 0, 313);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 4, 24025, "アヤネ", 3.71, 102301, "2030/12/17 14:59:59", 3, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 24, "2020/07/31 12:00:00", 0, 421);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24026, "アサヒ", 5.1, 192201, "2030/12/17 14:59:59", 1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 24, "2020/07/31 12:00:00", 0, 721);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24027, "部員３", 4.34, 192301, "2030/12/17 14:59:59", 3, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 24, "2020/07/31 12:00:00", 0, 821);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24028, "", 0, 192501, "2030/12/17 14:59:59", 1, "いい勝負だったよ\nまたやろうね", 24, "2020/07/31 12:00:00", 0, 521);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24029, "ミサト", 5.62, 113501, "2030/12/17 14:59:59", 2, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 24, "2020/07/31 12:00:00", -360, 101);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24030, "ミサト", 9.58, 113501, "2030/12/17 14:59:59", 2, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 24, "2020/07/31 12:00:00", -360, 102);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24031, "ミサト", 0, 113501, "2030/12/17 14:59:59", 2, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 24, "2020/07/31 12:00:00", -360, 103);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 2, 24032, "ミサト", 9.13, 113501, "2030/12/17 14:59:59", 1, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 24, "2020/07/31 12:00:00", -360, 104);
INSERT INTO `v1_55e849370286d8a6164f2bc88549b471536b90aab903f1c1c07bcd7e564d899c` VALUES (0, 10046, 1, 24033, "ミサト", 8.27, 113501, "2030/12/17 14:59:59", 2, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 24, "2020/07/31 12:00:00", -360, 105);
